def min_assignment(cost):
    n = len(cost)

    @lru_cache(maxsize=None)
    def go(i, used):
        if i == n:
            return 0
        return min(
            cost[i][j] + go(i + 1, used | (1 << j))
            for j in range(n)
            if not used & (1 << j)
        )

    return go(0, 0)

