def can_partition(xs):
    total = sum(xs)
    if total % 2:
        return False
    reachable = 1
    for x in xs:
        reachable |= reachable << x
    return bool(reachable >> (total // 2) & 1)

def min_difference(xs):
    total = sum(xs)
    reachable = 1
    for x in xs:
        reachable |= reachable << x
    half = total // 2
    best = max(s for s in range(half + 1) if reachable >> s & 1)
    return total - 2 * best

