class BIT:
    def __init__(self, n):
        self.n = n
        self.t = [0] * (n + 1)

    def add(self, i, delta):
        i += 1
        while i <= self.n:
            self.t[i] += delta
            i += i & -i

    def prefix(self, i):
        total, i = 0, i + 1
        while i > 0:
            total += self.t[i]
            i -= i & -i
        return total

    def range_sum(self, lo, hi):
        return self.prefix(hi) - (self.prefix(lo - 1) if lo else 0)

