from collections import deque

def shortest(graph, src, dst):
    prev, q = {src: None}, deque([src])
    while q:
        u = q.popleft()
        if u == dst:
            break
        for v in graph.get(u, ()):
            if v not in prev:
                prev[v] = u
                q.append(v)
    if dst not in prev:
        return None
    path, node = [], dst
    while node is not None:
        path.append(node)
        node = prev[node]
    return path[::-1]

