import heapq

def prim(graph, start):
    seen, heap, total, tree = {start}, list(graph[start]), 0, []
    heapq.heapify(heap)
    while heap:
        w, v = heapq.heappop(heap)
        if v in seen:
            continue
        seen.add(v)
        total += w
        tree.append((v, w))
        for nw, nv in graph[v]:
            if nv not in seen:
                heapq.heappush(heap, (nw, nv))
    return total, tree

