print(",".join(blob), serialize(deserialize(blob)) == blob)

END = "$"

def insert(root, word):
    node = root
    for ch in word:
        node = node.setdefault(ch, {})
    node[END] = True

def find(root, word):
    node = root
    for ch in word:
        if ch not in node:
            return None
        node = node[ch]
    return node

