def word_break(s, words):
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = True

    reachable = [True] + [False] * len(s)
    for i in range(len(s)):
        if not reachable[i]:
            continue
        node = root
        for j in range(i, len(s)):
            node = node.get(s[j])
            if node is None:
                break
            if "$" in node:
                reachable[j + 1] = True
    return reachable[-1]

