def middle(xs):
    slow = fast = 0
    while fast + 1 < len(xs):
        slow, fast = slow + 1, fast + 2
    return xs[slow]

def has_duplicate_cycle(nums):
    slow = fast = nums[0]
    while True:
        slow = nums[slow]
        fast = nums[nums[fast]]
        if slow == fast:
            break
    slow = nums[0]
    while slow != fast:
        slow, fast = nums[slow], nums[fast]
    return slow

