from collections import Counter

def find_anagrams(s, pattern):
    need, window = Counter(pattern), Counter()
    k, out = len(pattern), []
    for i, ch in enumerate(s):
        window[ch] += 1
        if i >= k:
            drop = s[i - k]
            window[drop] -= 1
            if window[drop] == 0:
                del window[drop]
        if window == need:
            out.append(i - k + 1)
    return out

print(find_anagrams("cbaebabacd", "abc"))

def longest_at_most_k_distinct(s, k):
    counts, left, best = {}, 0, 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            counts[s[left]] -= 1
            if counts[s[left]] == 0:
                del counts[s[left]]
            left += 1
        best = max(best, right - left + 1)
    return best

def min_subarray_at_least(xs, target):
    left, cur, best = 0, 0, len(xs) + 1
    for right, x in enumerate(xs):
        cur += x
        while cur >= target:
            best = min(best, right - left + 1)
            cur -= xs[left]
            left += 1
    return best if best <= len(xs) else 0

